import{f as o,n as i}from"./shared-CAKwAg2C.js";const u={"LEARN HOW THE INTERNET WORKS":"COMMENT FONCTIONNE INTERNET","NOW LEARNING":"LEÇON EN COURS","OSI LAYER":"COUCHE OSI","LEARNING PROGRESS":"VOTRE PROGRESSION",COMPLETE:"TERMINÉES","IN PROGRESS":"EN COURS","{pct}% complete":"{pct} % terminé","DESIGNED BY":"CONÇU PAR","Dilum Sanjaya on X":"Dilum Sanjaya sur X","Layer {n}: {name}":"Couche {n} : {name}",Physical:"Physique","Data Link":"Liaison de données",Network:"Réseau",Transport:"Transport",Session:"Session",Presentation:"Présentation",Application:"Application","OVERVIEW · {n} STEPS":"VUE D’ENSEMBLE · {n} ÉTAPES","STEP {n}/{total} · {title}":"ÉTAPE {n}/{total} · {title}","LESSON COMPLETE":"LEÇON TERMINÉE",PROTOCOLS:"PROTOCOLES",Protocols:"Protocoles",Language:"Langue",Theme:"Thème","Light mode":"Mode clair","Dark mode":"Mode sombre","INTERNET PROTOCOLS":"PROTOCOLES INTERNET",More:"Plus","Close the protocol list":"Fermer la liste des protocoles","Close (Esc)":"Fermer (Échap)",ALL:"TOUS",CORE:"BASE",APPLICATION:"APPLICATION",SECURITY:"SÉCURITÉ",NETWORK:"RÉSEAU",SEQUENCE:"SÉQUENCE",View:"Vue","Switch view (V)":"Changer de vue (V)","Network diagram":"Schéma du réseau","Sequence diagram":"Diagramme de séquence","STEP {n}":"ÉTAPE {n}","PROTOCOL OVERVIEW":"VUE D’ENSEMBLE","STEP DETAILS":"ÉTAPE EN COURS","LESSON SUMMARY":"RÉSUMÉ",OVERVIEW:"DÉBUT",ACTIVE:"ACTIF","STEP {n} OF {total}":"ÉTAPE {n} SUR {total}","PACKET {n} OF {total}":"PAQUET {n} SUR {total}","PACKETS {from}–{to} OF {total}":"PAQUETS {from}–{to} SUR {total}","{n} LOST":"{n} PERDUS","1 LOST":"1 PERDU",ENCRYPTED:"CHIFFRÉ","LOST ON THE WAY":"PERDU EN ROUTE","PACKET FLOW":"FLUX DE PAQUETS","Colour key":"Légende des couleurs","Playback speed":"Vitesse de lecture","Previous step (←)":"Étape précédente (←)","Previous step":"Étape précédente","Play / pause (Space)":"Lecture / pause (Espace)",PLAY:"LECTURE",PAUSE:"PAUSE",REPLAY:"REVOIR",STEP:"AVANCER","One packet at a time":"Un paquet à la fois",RESET:"RÉINITIALISER",Reset:"Réinitialiser","Back to the overview (Esc)":"Retour à la vue d’ensemble (Échap)","NO.":"N°",TIME:"TEMPS",SOURCE:"SOURCE",DESTINATION:"DESTINATION",PROTOCOL:"PROTOCOLE",INFO:"INFO",SIZE:"TAILLE","No packets on the wire yet.":"Aucun paquet sur le réseau pour l’instant.",LOST:"PERDU","Packet inspector":"Inspecteur de paquets","Previous packet":"Paquet précédent","Previous packet (←)":"Paquet précédent (←)","Next packet":"Paquet suivant","Next packet (→)":"Paquet suivant (→)",Close:"Fermer","E.G.":"EX.","an example value: it differs in every real capture":"une valeur d’exemple : elle change à chaque capture réelle","bytes the lesson can’t show: encrypted, random, or a file’s contents":"octets que la leçon ne peut pas montrer : chiffrés, aléatoires ou contenu d’un fichier",BYTES:"OCTETS","{n} in this frame":"{n} dans cette trame","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Cette ligne représente {n} segments TCP portant un message de {size} octets ; le premier segment est affiché","This packet was lost on the way":"Ce paquet s’est perdu en route",Padding:"Bourrage","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · BAIL 24 H","2 SEGMENTS":"2 SEGMENTS","3 SEGMENTS":"3 SEGMENTS","3 DATAGRAMS":"3 DATAGRAMMES","4 DATAGRAMS":"4 DATAGRAMMES","203.0.113.10 IS NOT LOCAL":"203.0.113.10 N’EST PAS LOCALE","250 QUEUED":"250 EN FILE",ANSWER:"RÉPONSE","APP COVERS THE 20 MS GAP":"L’APPLI COMBLE LE TROU DE 20 MS","APP DATA":"DONNÉES APPLI","ARP REPLY":"RÉPONSE ARP","ARP REQUEST":"REQUÊTE ARP","ARRIVED WITH TTL 116":"ARRIVÉ AVEC TTL 116","AUTH FAILURE":"ÉCHEC AUTH","At QUIT":"Au QUIT","CACHED · TTL 3600 S":"EN CACHE · TTL 3600 S","CERTIFICATE VALID":"CERTIFICAT VALIDE","CHAIN LEADS TO A TRUSTED ROOT":"LA CHAÎNE MÈNE À UNE RACINE DE CONFIANCE","CHANNEL OPEN":"OUVRIR UN CANAL",CONFIRMED:"CONFIRMÉ","DNS QUERY":"REQUÊTE DNS","DNS REPLY":"RÉPONSE DNS","DUP ACK":"ACK DUPLIQUÉ","EACH KEY IS ITS OWN PACKET":"CHAQUE TOUCHE, SON PAQUET",ECHO:"ÉCHO","ECHO REPLY":"RÉPONSE ÉCHO","ECHO REQUEST":"REQUÊTE ÉCHO",ENTER:"ENTRÉE","FRAME 7 LOST · NOT RESENT":"TRAME 7 PERDUE · PAS RENVOYÉE","HOP 2 · 198.51.100.1":"SAUT 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"LA CLÉ D’HÔTE CORRESPOND À KNOWN_HOSTS","IN BOB’S MAILBOX":"DANS LA BOÎTE DE BOB","IP PACKET":"PAQUET IP",MESSAGE:"MESSAGE","MESSAGE 1 DELETED":"MESSAGE 1 SUPPRIMÉ","NEW MAIL ARRIVED":"NOUVEAU COURRIER ARRIVÉ","NO IP ADDRESS YET":"PAS ENCORE D’ADRESSE IP","NOT IN CACHE":"PAS EN CACHE","OFFER KEY":"PROPOSE UNE CLÉ",OUTPUT:"SORTIE","PASSWORD IN PLAIN TEXT":"MOT DE PASSE EN CLAIR",REFERRAL:"RÉFÉRENCE",REPLY:"RÉPONSE",RESEND:"RENVOI","SEGMENT 1 LOST":"SEGMENT 1 PERDU","SFTP or FTPS":"SFTP ou FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP, ou FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"SECRET PARTAGÉ CALCULÉ",SIGNED:"SIGNÉ","STILL ON SERVER · \\SEEN":"TOUJOURS SUR LE SERVEUR · \\SEEN",SUCCESS:"SUCCÈS","TIME EXCEEDED":"TEMPS DÉPASSÉ","TIME=34MS TTL=52":"TEMPS=34 MS TTL=52",UNREACHABLE:"INACCESSIBLE",VERSION:"VERSION","VOICE 1":"VOIX 1","+OK or -ERR":"+OK ou -ERR",".com Server":"Serveur .com",Authoritative:"Faisant autorité","Log In":"Connexion",Key:"Clé",Why:"Pourquoi",End:"Fin","MACs, in":"MAC, entrée",Internet:"Internet",Router:"Routeur","Router 192.168.1.1":"Routeur 192.168.1.1","Router: 192.168.1.1":"Routeur : 192.168.1.1",Routers:"Routeurs",Hardware:"Matériel",Audio:"Audio",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"Visible",Tickets:"Tickets","4, 20 bytes":"4, 20 octets","20–60 bytes":"20–60 octets","20–60 bytes (IPv4)":"20–60 octets (IPv4)","8 bytes (TCP: 20+)":"8 octets (TCP : 20+)","32 bytes (Windows)":"32 octets (Windows)","1,460 bytes (MSS)":"1,460 octets (MSS)","78 bytes (seq 1–78)":"78 octets (seq 1–78)","bytes 1461–2920":"octets 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 octets)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 octets)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 octets), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 octets)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 octets)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 octets)',"32 bits (IPv4), 128 (IPv6)":"32 bits (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 routeurs)","52 (64 − 12 routers)":"52 (64 − 12 routeurs)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 octets","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 octets (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + audio"},d={"Hypertext Transfer Protocol":"Transfert hypertexte","HTTP Secure":"HTTP sécurisé","Transmission Control Protocol":"Contrôle de transmission","User Datagram Protocol":"Datagrammes utilisateur","Internet Protocol":"Protocole Internet","Domain Name System":"Système de noms de domaine","Dynamic Host Configuration":"Configuration dynamique d’hôte","Internet Control Message":"Messages de contrôle Internet","Simple Mail Transfer Protocol":"Transfert simple de courrier","Post Office Protocol v3":"Protocole de bureau de poste v3","Internet Message Access":"Accès aux messages Internet","File Transfer Protocol":"Transfert de fichiers","Secure Shell":"Shell sécurisé","Transport Layer Security":"Sécurité de la couche transport",Internet:"Internet",Client:"Client",Router:"Routeur","DNS Resolver":"Résolveur DNS","Web Server":"Serveur web","Root Server":"Serveur racine",".com TLD Server":"Serveur TLD .com","Authoritative Server":"Serveur faisant autorité","Mail Server":"Serveur de messagerie","Web Communication":"Communication web",Request:"Requête",Response:"Réponse","Data ACKs not shown":"ACK de données non affichés","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP est le protocole du web : un client demande une ressource, comme une page HTML, et le serveur répond par un code d’état, des en-têtes et généralement un corps. Chaque échange se compose d’une requête et d’une réponse, écrites en texte lisible en HTTP/1.1.",Layer:"Couche","Application (Layer 7)":"Application (couche 7)","Default Port":"Port par défaut",Transport:"Transport","Data Format":"Format des données","Text (headers + optional body)":"Texte (en-têtes + corps facultatif)","Common Methods":"Méthodes courantes","Defined In":"Défini dans","Page delivered":"Page livrée","One request, one response":"Une requête, une réponse","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"En moins d’un dixième de seconde, l’ordinateur a cherché une adresse, ouvert une connexion TCP et échangé une requête et une réponse HTTP, le tout lisible par n’importe qui sur le trajet. Appuyez sur REVOIR pour tout revoir.","Round trips":"Allers-retours","Total time":"Durée totale","Page size":"Taille de la page","Sent as 9 TCP segments":"Envoyée en 9 segments TCP","Client Request":"Requête du client","Browser prepares the request":"Le navigateur prépare la requête","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Vous ouvrez http://www.example.com. Le navigateur va envoyer une requête GET, mais les paquets voyagent vers des adresses IP, pas vers des noms : il lui faut donc d’abord l’adresse du serveur. (Les navigateurs essaient désormais https:// en premier ; ceci est la version non chiffrée.)",Method:"Méthode","Next hop":"Prochain saut","Router 192.168.1.1":"Routeur 192.168.1.1","DNS Resolution":"Résolution DNS","Finds the server’s IP address":"Trouve l’adresse IP du serveur","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"L’ordinateur demande au serveur DNS que DHCP lui a attribué, 8.8.8.8, l’adresse de www.example.com. La requête passe par le port UDP 53 et la réponse est un enregistrement A contenant l’adresse IPv4. (Sur un réseau IPv6, il demanderait aussi un enregistrement AAAA.)",Resolver:"Résolveur","8.8.8.8 (had it cached)":"8.8.8.8 (l’avait en cache)","UDP, port 53":"UDP, port 53",Answer:"Réponse","TCP Connection":"Connexion TCP","Establishes a reliable link":"Établit un lien fiable","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP fonctionne au-dessus de TCP. Avant que la moindre donnée de la page circule, l’ordinateur et le serveur ouvrent une connexion vers le port 80 par une poignée de main en trois temps : SYN, SYN-ACK, ACK.","Server port":"Port du serveur","Client port":"Port du client",Handshake:"Poignée de main","HTTP Exchange":"Échange HTTP","Request and response messages":"Messages de requête et de réponse","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Le navigateur envoie une requête GET avec un en-tête Host. Le serveur répond 200 OK avec le HTML dans le corps : 12.2 KB, trop gros pour un seul paquet, donc TCP le découpe en 9 segments d’au plus 1460 octets (dessinés ici comme un seul).",Status:"Statut",Body:"Corps","Sent as":"Envoyée en","12.2 KB in 9 segments":"12.2 KB en 9 segments","Page Rendering":"Affichage de la page","Browser displays the content":"Le navigateur affiche le contenu","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Le navigateur analyse le HTML et dessine la page. Chaque CSS, image ou script lié lancerait d’autres requêtes comme celle-ci, en réutilisant la connexion ouverte quand c’est possible.",Document:"Document",Connection:"Connexion","Kept open for reuse":"Gardée ouverte pour être réutilisée","Seen on the laptop’s home network":"Vu sur le réseau domestique de l’ordinateur",Destination:"Destination","The router: anything beyond the home network goes to it first.":"Le routeur : tout ce qui sort du réseau domestique passe d’abord par lui.",Source:"Source","The laptop’s network card.":"La carte réseau de l’ordinateur.",Type:"Type","What the frame carries.":"Ce que transporte la trame.","Version, header length":"Version, longueur d’en-tête","IPv4, with no options.":"IPv4, sans options.","Priority and congestion marks; 0 means ordinary traffic.":"Marques de priorité et de congestion ; 0 signifie un trafic ordinaire.","Total length":"Longueur totale","This header and everything inside it.":"Cet en-tête et tout ce qu’il contient.",Identification:"Identification","Lets the receiver reassemble the pieces if the packet gets split.":"Permet au destinataire de réassembler les morceaux si le paquet est fragmenté.",Flags:"Drapeaux",none:"aucun","Routers may split it if a link is too small.":"Les routeurs peuvent le fragmenter si un lien est trop petit.","Time to live":"Durée de vie","Windows starts at 128.":"Windows commence à 128.",Protocol:"Protocole","Header checksum":"Somme de contrôle de l’en-tête","Covers this header only; every router recomputes it after lowering the TTL.":"Ne couvre que cet en-tête ; chaque routeur la recalcule après avoir diminué le TTL.","Source port":"Port source","Destination port":"Port de destination",Length:"Longueur","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"En-tête UDP et données. C’est tout UDP : ni numérotation, ni accusés de réception.",Checksum:"Somme de contrôle","Covers the header, the data and the IP addresses.":"Couvre l’en-tête, les données et les adresses IP.","Transaction ID":"ID de transaction","Picked at random; the answer must carry the same one.":"Choisi au hasard ; la réponse doit porter le même.","0x0100: query, RD (recursion desired)":"0x0100 : requête, RD (récursion souhaitée)",Questions:"Questions",Answers:"Réponses","Authority records":"Enregistrements d’autorité","Additional records":"Enregistrements additionnels",Question:"Question","www.example.com, type A, class IN":"www.example.com, type A, classe IN","The laptop.":"L’ordinateur.","The router’s side facing the home network.":"Le côté du routeur tourné vers le réseau domestique.","Started at 128; 10 routers on the way each took 1.":"Parti de 128 ; chacun des 10 routeurs du trajet a retiré 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180 : réponse, RD (récursion souhaitée), RA (récursion disponible)","DF (don’t fragment)":"DF (ne pas fragmenter)","Routers must not split it; if it’s too big they report back instead.":"Les routeurs ne doivent pas le fragmenter ; s’il est trop gros, ils le signalent en retour.","Picked by the laptop’s system for this connection.":"Choisi par le système de l’ordinateur pour cette connexion.","Sequence number":"Numéro de séquence","This side’s starting number. Shown as 0; the real one is random.":"Le numéro de départ de ce côté. Affiché comme 0 ; le vrai est aléatoire.","Real sequence number":"Numéro de séquence réel",Acknowledgment:"Accusé de réception","0 (not used yet)":"0 (pas encore utilisé)","A first SYN has nothing to acknowledge.":"Un premier SYN n’a rien à accuser.","Header length":"Longueur d’en-tête","20 bytes, plus 12 of options.":"20 octets, plus 12 d’options.",Window:"Fenêtre","How much more data this side can take right now.":"La quantité de données que ce côté peut encore recevoir maintenant.","Covers the header, the data and the IP addresses, so damage is caught.":"Couvre l’en-tête, les données et les adresses IP, pour détecter les dégâts.","Urgent pointer":"Pointeur d’urgence",Options:"Options","Maximum segment size":"Taille maximale de segment","The most data this side wants in one segment.":"Le maximum de données que ce côté veut dans un segment.","Spacing, so the next option lines up.":"Remplissage, pour aligner l’option suivante.","Window scale":"Facteur d’échelle de fenêtre","Window values are multiplied by this, so windows can be larger than 64 KB.":"Les valeurs de fenêtre sont multipliées par ce facteur, pour des fenêtres de plus de 64 KB.","SACK permitted":"SACK autorisé",yes:"oui","This side understands selective acknowledgements.":"Ce côté comprend les accusés de réception sélectifs.","Started at 64; 12 routers on the way each took 1.":"Parti de 64 ; chacun des 12 routeurs du trajet a retiré 1.","The next byte this side expects: everything before it has arrived.":"Le prochain octet attendu par ce côté : tout ce qui précède est arrivé.","Position of this segment’s first byte, counted from this side’s SYN.":"Position du premier octet de ce segment, comptée depuis le SYN de ce côté.",Padding:"Bourrage","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Les trames Ethernet font au moins 60 octets (64 avec la somme de contrôle ajoutée par la carte), donc les plus courtes sont complétées.",Text:"Texte","covers bytes not shown here":"couvre des octets non affichés ici","12,500 bytes: the HTML page":"12,500 octets : la page HTML","The page itself; its contents are not part of the lesson.":"La page elle-même ; son contenu ne fait pas partie de la leçon.","Secure Web":"Web sécurisé","TLS handshake":"Négociation TLS","HTTP request":"Requête HTTP","HTTP response":"Réponse HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS, c’est HTTP envoyé dans une connexion TLS chiffrée. TLS prouve par un certificat que le serveur est bien celui qu’il prétend être, convient de nouvelles clés de chiffrement, puis protège chaque requête et réponse contre la lecture ou la modification en route.","Application (HTTP over TLS)":"Application (HTTP sur TLS)",Security:"Sécurité","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 encore courant)",Proves:"Prouve","Server identity (certificate)":"L’identité du serveur (certificat)","Secure page delivered":"Page sécurisée livrée","Encrypted, except the lookup":"Chiffrée, sauf la résolution DNS","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Le navigateur a cherché l’adresse en DNS non chiffré, ouvert une connexion TCP, vérifié le certificat du serveur et convenu des clés en un seul aller-retour. Chaque octet HTTP a ensuite voyagé chiffré. Appuyez sur REVOIR pour tout revoir.",Cipher:"Chiffrement","Still visible":"Toujours visible","IPs, server name, sizes":"IP, nom du serveur, tailles","Secure Request":"Requête sécurisée","Browser asks for https://":"Le navigateur demande https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Vous tapez https://www.example.com. Le « s » indique au navigateur de protéger la connexion par TLS, sur le port 443 par défaut. Avant même de se connecter, il doit encore trouver l’adresse IP du serveur.",Port:"Port","DNS Lookup":"Résolution DNS","Same lookup as HTTP, not encrypted":"La même résolution qu’en HTTP, non chiffrée","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"La résolution est exactement la même qu’en HTTP simple : une requête vers 8.8.8.8 sur le port UDP 53. Elle n’est pas chiffrée, donc n’importe qui sur le trajet peut voir quel nom vous avez demandé, sauf si le navigateur utilise DNS over HTTPS.",Encrypted:"Chiffré","No (plain DNS)":"Non (DNS en clair)","TCP Handshake":"Poignée de main TCP","Opens a connection to port 443":"Ouvre une connexion vers le port 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS s’appuie sur TCP, donc la même poignée de main en trois temps vient d’abord, cette fois vers le port 443. Rien n’est encore chiffré.","TLS Handshake":"Négociation TLS","Agrees on keys, checks the certificate":"Convient des clés, vérifie le certificat","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Le navigateur propose des suites de chiffrement et des parts de clé, dont un hybride post-quantique. Le serveur le choisit et envoie sa propre part, puis son certificat, déjà chiffré. Le navigateur le vérifie auprès des autorités en qui il a confiance.",Version:"Version","Key exchange":"Échange de clés","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (hybride)","Server name":"Nom du serveur","Sent in clear (SNI)":"Envoyé en clair (SNI)","key shares: hybrid + x25519":"parts de clé : hybride + x25519","cipher: AES_128_GCM_SHA256":"chiffrement : AES_128_GCM_SHA256","then encrypted: cert, Finished":"puis chiffré : cert., Finished","handshake complete (encrypted)":"négociation terminée (chiffrée)","Encrypted Exchange":"Échange chiffré","HTTP inside TLS records":"HTTP dans des enregistrements TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"Le GET et le 200 OK sont les mêmes messages HTTP qu’avant, scellés dans des enregistrements TLS qui ressemblent à des « données d’application » aléatoires sur le réseau. Le serveur remet aussi deux tickets de session, pour qu’une visite ultérieure puisse sauter une partie de la négociation.",Inside:"À l’intérieur","GET / and 200 OK":"GET / et 200 OK",Tickets:"Tickets","2, for faster reconnects":"2, pour des reconnexions plus rapides","inside: GET / HTTP/1.1":"dedans : GET / HTTP/1.1","outside: encrypted bytes":"dehors : octets chiffrés","inside: HTTP/1.1 200 OK":"dedans : HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"dehors : 12.9 KB, 9 segments","Browser shows the padlock":"Le navigateur affiche le cadenas","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Le navigateur déchiffre la réponse, dessine la page et affiche un cadenas : la connexion est privée et le serveur a prouvé son identité. L’en-tête Strict-Transport-Security lui indique d’utiliser HTTPS pour ce site désormais.",Remembers:"Retient","HTTPS only (HSTS), 1 year":"HTTPS uniquement (HSTS), 1 an","Server Hello + encrypted handshake, 3 segments":"Server Hello + négociation chiffrée, 3 segments","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (chiffré)","Application Data (HTTP request)":"Application Data (requête HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (chiffré)","Application Data (HTTP response), 9 segments":"Application Data (réponse HTTP), 9 segments",Record:"Enregistrement","Content type":"Type de contenu","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"L’enregistrement d’un Client Hello indique TLS 1.0 pour que les anciens équipements intermédiaires le laissent passer ; les vraies versions sont proposées à l’intérieur.","Handshake type":"Type de négociation",Contents:"Contenu","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Tout ce que le navigateur prend en charge. Les navigateurs varient quelques détails d’une connexion à l’autre.","Server name (SNI)":"Nom du serveur (SNI)","Versions offered":"Versions proposées","Key shares":"Parts de clé","App protocols (ALPN)":"Protocoles d’application (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"Les enregistrements TLS 1.3 indiquent 1.2 à l’extérieur, par compatibilité.","The server’s choices and its half of the hybrid key exchange.":"Les choix du serveur et sa moitié de l’échange de clés hybride.","Cipher suite":"Suite de chiffrement","Key share":"Part de clé","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"N’a aucun rôle en TLS 1.3 ; envoyé pour que les équipements intermédiaires voient une négociation familière.","Every encrypted record says Application Data on the outside; the real type is inside.":"Tout enregistrement chiffré indique Application Data à l’extérieur ; le vrai type est à l’intérieur.","Encrypted data":"Données chiffrées","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Texte chiffré, terminé par une étiquette de 16 octets qui révèle toute modification. Seules les deux extrémités peuvent le lire.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN : http/1.1), Certificate (la chaîne), Certificate Verify (la signature), Finished","Finished: a check value over the whole handshake":"Finished : une valeur de contrôle sur toute la négociation","The HTTP request":"La requête HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket : permet de reprendre la session lors d’une visite ultérieure","The HTTP response, then the 12,500-byte page":"La réponse HTTP, puis la page de 12,500 octets","Reliable Delivery":"Livraison fiable","Handshake and ACKs":"Poignée de main et ACK","Data from laptop":"Données de l’ordinateur","Data from server":"Données du serveur","Closing (FIN)":"Fermeture (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP transforme la livraison de paquets « au mieux » d’Internet en un flux d’octets fiable et ordonné. Il numérote chaque octet, accuse réception de ce qui arrive, renvoie ce qui se perd et règle le rythme de l’émetteur pour ne submerger ni l’autre côté ni le réseau.","Transport (Layer 4)":"Transport (couche 4)","Three-way handshake":"Poignée de main en trois temps",Reliability:"Fiabilité","Sequence numbers + ACKs":"Numéros de séquence + ACK",Recovery:"Récupération",Retransmission:"Retransmission",Header:"En-tête","Connection closed":"Connexion fermée","Every byte accounted for":"Chaque octet compté","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP a ouvert une connexion, numéroté et acquitté chaque octet, repéré un trou et renvoyé uniquement le segment manquant, puis fermé proprement les deux sens. curl a reçu tous les octets dans l’ordre sans jamais voir la perte. Appuyez sur REVOIR pour tout revoir.",Segments:"Segments","14 (1 lost, 1 resent)":"14 (1 perdu, 1 renvoyé)","Bytes delivered":"Octets livrés","78 up, 2,920 down":"78 en montée, 2,920 en descente","Loss found by":"Perte détectée par","Duplicate ACK + SACK":"ACK dupliqué + SACK","Open Connection":"Ouvrir la connexion","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl connaît déjà l’adresse du serveur. Avant que la moindre donnée circule, les deux côtés choisissent un numéro de séquence initial et le confirment : SYN, SYN-ACK, ACK. Les numéros sont ici relatifs ; les vrais partent d’une valeur aléatoire.",Server:"Serveur","203.0.113.10, port 80":"203.0.113.10, port 80","Send Data":"Envoyer des données","Every byte is numbered":"Chaque octet est numéroté","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl envoie sa requête HTTP de 78 octets : les octets 1 à 78. Le numéro d’ACK du serveur, 79, est le prochain octet qu’il attend, ce qui signifie que tout ce qui précède est arrivé.",Sent:"Envoyé","79 = next byte expected":"79 = prochain octet attendu","Two Segments Back":"Deux segments en retour","One of them is lost":"L’un d’eux se perd","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Le serveur répond avec 2,920 octets : deux segments pleins de 1,460 octets, le maximum qui tient ici dans un paquet, envoyés à la suite. Le premier se perd quelque part sur Internet ; le second passe.","Segment 1":"Segment 1","bytes 1–1460 (lost)":"octets 1–1460 (perdu)","Segment 2":"Segment 2","Segment size":"Taille de segment","seq=1 and seq=1461":"seq=1 et seq=1461","the first is lost":"le premier se perd","A Gap Is Noticed":"Un trou est repéré","Duplicate ACK with SACK":"ACK dupliqué avec SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Les octets 1461–2920 arrivent, mais jamais les octets 1–1460. Un ACK ne peut compter que les octets reçus dans l’ordre, donc l’ordinateur répète aussitôt l’ACK 1 et ajoute un bloc SACK indiquant qu’il a déjà 1461–2920.","1 (still waiting for byte 1)":"1 (attend toujours l’octet 1)","holds bytes 1461–2920":"a les octets 1461–2920","At once, not delayed":"Aussitôt, sans délai","sack: has 1461–2920":"sack : a 1461–2920","Resend the Gap":"Renvoyer le trou","Only the missing bytes":"Seulement les octets manquants","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"Le SACK indique au serveur exactement ce qui manque, donc il renvoie seulement le segment 1, et l’ordinateur acquitte tout. Si aucun ACK n’était revenu, des minuteurs auraient pris le relais : d’abord une sonde après environ deux allers-retours, puis le délai de retransmission (au moins 200 ms sous Linux).",Resent:"Renvoyé","bytes 1–1460 only":"octets 1–1460 seulement","Next ACK":"ACK suivant","2921 (everything)":"2921 (tout)","curl saw":"curl a vu","Every byte, in order":"Tous les octets, dans l’ordre","just the missing segment":"seulement le segment manquant","Close Connection":"Fermer la connexion","Each side says goodbye":"Chaque côté dit au revoir","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl a terminé, il ferme donc. Chaque sens se ferme séparément : l’ordinateur envoie FIN et le serveur l’acquitte, puis le serveur envoie son propre FIN et l’ordinateur l’acquitte. L’ordinateur garde les détails de la connexion un moment (TIME-WAIT).","Closed by":"Fermée par","A FIN from each side":"Un FIN de chaque côté",Order:"Ordre",Then:"Puis","Laptop waits (TIME-WAIT)":"L’ordinateur attend (TIME-WAIT)",Data:"Données","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 octets : la réponse HTTP, octets 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 octets : la réponse HTTP, octets 1461–2920","has 1461–2920":"a 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Des octets arrivés après le trou, donc seul le trou doit être renvoyé.","Fast Datagrams":"Datagrammes rapides","Your voice":"Votre voix","Their voice":"Sa voix","Media Server":"Serveur multimédia","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP envoie des données dans des paquets indépendants appelés datagrammes, sans connexion, sans accusés de réception ni renvois. C’est ce qui le rend rapide et léger : idéal pour la voix, la vidéo, les jeux et le DNS, où une réponse tardive est pire qu’une réponse manquante.",None:"Aucune","None (no ACKs, no resends)":"Aucune (ni ACK, ni renvoi)",Ordering:"Ordre","Not guaranteed":"Non garanti","Call keeps flowing":"L’appel continue","Fast, simple, no guarantees":"Rapide, simple, sans garanties","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"L’audio a commencé dès le premier paquet, chaque datagramme a voyagé seul, et celui qui s’est perdu a tout simplement disparu : UDP ne s’en est jamais aperçu. L’appli a comblé le trou et l’appel a continué. Appuyez sur REVOIR pour tout revoir.",Datagrams:"Datagrammes","11 (1 lost, never resent)":"11 (1 perdu, jamais renvoyé)","Setup time":"Temps d’établissement","0 ms (no handshake)":"0 ms (pas de poignée de main)",Shown:"Montré","The first 0.2 s of a call":"Les 0.2 premières secondes d’un appel","Send Right Away":"Envoyer tout de suite","No handshake, data goes first":"Pas de poignée de main, les données partent d’abord","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Une appli d’appel connaît déjà l’adresse et le port du serveur multimédia depuis la connexion au compte. Elle n’ouvre aucune connexion : le tout premier datagramme transporte déjà 20 ms de votre voix, derrière un en-tête UDP de 8 octets.",Setup:"Établissement",Ports:"Ports","92 B of audio, no setup":"92 B d’audio, sans établissement","A Stream of Datagrams":"Un flux de datagrammes","One every 20 ms, each on its own":"Un toutes les 20 ms, chacun seul","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"L’appli continue d’envoyer un datagramme toutes les 20 ms. Chacun est autonome, avec son propre en-tête et sans lien avec les autres. UDP ne les numérote pas, et rien ne revient confirmer leur arrivée.",Rate:"Débit","1 datagram / 20 ms":"1 datagramme / 20 ms",Numbering:"Numérotation","None in UDP itself":"Aucune dans UDP lui-même",Confirmation:"Confirmation","None (no ACKs)":"Aucune (pas d’ACK)","voice frames 2–5":"trames vocales 2–5","each with its own 8-byte header":"chacune avec son en-tête de 8 octets","Lost on the Way":"Perdu en route","Nobody resends it":"Personne ne le renvoie","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"La trame 7 se perd quelque part sur Internet. Le serveur multimédia ne la redemande jamais et UDP ne prévient jamais l’ordinateur : il n’y a pas d’accusés de réception dont l’absence se remarquerait. Les datagrammes suivants arrivent normalement.",Lost:"Perdue","Voice frame 7":"Trame vocale 7","Never (no ACKs)":"Jamais (pas d’ACK)",Missing:"Manquant","20 ms of audio":"20 ms d’audio","voice frames 6–8":"trames vocales 6–8","frame 7 is lost":"la trame 7 se perd","Replies Come Back":"Les réponses reviennent","The other voice comes back":"L’autre voix revient","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"La voix de l’autre personne arrive de la même façon, en datagrammes séparés envoyés au port 50000. Ils peuvent entrer parce que votre routeur a retenu le port de sortie en traduisant votre adresse (NAT).",Direction:"Sens","Independent of ours":"Indépendant du nôtre","Through NAT":"À travers le NAT","Router remembers the port":"Le routeur retient le port","the other person’s voice":"la voix de l’autre personne","sent to port 50000":"envoyée au port 50000","The App Decides":"L’appli décide","Reliability is up to the app":"La fiabilité dépend de l’appli","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"L’appli d’appel numérote ses propres trames (c’est le rôle de RTP), elle voit donc que la trame 7 manque et masque le trou de 20 ms au lieu d’attendre. Attendre un renvoi retarderait tout l’appel.","App’s job (e.g. RTP)":"Le travail de l’appli (ex. RTP)",Loss:"Perte","Hidden by the app":"Masquée par l’appli","Also on UDP":"Aussi sur UDP","DNS, games, QUIC":"DNS, jeux, QUIC","Version etc.":"Version, etc.","2, no padding, no extension, no CSRCs":"2, sans bourrage, sans extension, sans CSRC","Marker, payload type":"Marqueur, type de charge utile","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, convenu à l’établissement de l’appel)","Counts up by one per packet, so the app can spot a missing or late one.":"Augmente de un par paquet, pour que l’appli repère un paquet manquant ou en retard.",Timestamp:"Horodatage","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Horloge audio à 48,000 par seconde : +960 par trame de 20 ms.","Identifies this audio stream.":"Identifie ce flux audio.",Audio:"Audio","80 bytes of Opus audio (20 ms)":"80 octets d’audio Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, convenu à l’établissement de l’appel)","Addressing & Routing":"Adressage et routage","Outgoing packet":"Paquet sortant",Reply:"Réponse","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP donne une adresse à chaque appareil et achemine les paquets de réseau en réseau. Chaque routeur ne regarde que l’adresse de destination pour choisir le prochain saut. IP fonctionne « au mieux » : il ne promet ni la livraison ni l’ordre. TCP ajoute cela par-dessus.","Network (Layer 3)":"Réseau (couche 3)",Address:"Adresse","Lowered by 1 at each router":"Diminue de 1 à chaque routeur",Delivery:"Livraison","Best effort":"Au mieux","There and back":"Aller et retour","Twelve routers each way":"Douze routeurs dans chaque sens","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"L’ordinateur a envoyé le paquet à son routeur, qui y a mis son adresse publique. Douze routeurs au total l’ont relayé d’après la seule adresse de destination, et la réponse est revenue de la même façon. Appuyez sur REVOIR pour tout revoir.",Routers:"Routeurs","12 each way (1 home + 11)":"12 dans chaque sens (1 domestique + 11)","TTL at server":"TTL au serveur","116 (sent with 128)":"116 (envoyé avec 128)","Rewritten by NAT":"Réécrit par le NAT","Source out, destination back":"Source à l’aller, destination au retour","IPv4 (IPv6 works alike)":"IPv4 (IPv6 fonctionne pareil)","Local or Not?":"Local ou pas ?","Compare the address with the subnet":"Comparer l’adresse au sous-réseau","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"L’ordinateur a l’adresse 192.168.1.10 avec un masque /24, donc son propre réseau va de 192.168.1.0 à 192.168.1.255. Le serveur, 203.0.113.10, est hors de cette plage, donc le paquet doit passer par la passerelle par défaut : le routeur de la maison.",Laptop:"Ordinateur","Local range":"Plage locale",Gateway:"Passerelle","Find the Router":"Trouver le routeur","ARP turns an IP into a MAC":"ARP transforme une IP en MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Sur le réseau local, les trames sont livrées par adresse MAC. Si la MAC du routeur n’est pas dans le cache ARP de l’ordinateur, celui-ci diffuse « qui a 192.168.1.1 ? » et le routeur répond avec son adresse MAC.",Asks:"Demande","Who has 192.168.1.1?":"Qui a 192.168.1.1 ?","Sent to":"Envoyé à","Everyone (broadcast)":"Tout le monde (diffusion)",Learns:"Apprend","Router’s MAC address":"L’adresse MAC du routeur","who has 192.168.1.1?":"qui a 192.168.1.1 ?","tell 192.168.1.10":"répondre à 192.168.1.10","Send the Packet":"Envoyer le paquet","Addresses, TTL and protocol":"Adresses, TTL et protocole","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"L’en-tête IP contient les adresses source et destination, un TTL et le protocole transporté. Ici, il contient un SYN TCP vers le port 443. Windows démarre le TTL à 128 (Linux et macOS utilisent 64).","From → to":"De → vers","TTL 128 · protocol TCP":"TTL 128 · protocole TCP","NAT, Then Hop by Hop":"NAT, puis saut par saut","The router rewrites and forwards":"Le routeur réécrit et transmet","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Le routeur remplace la source privée par son adresse publique 198.51.100.7 (et ici le port 52344 par 40112), note la correspondance et abaisse le TTL à 127. Puis 11 routeurs sur Internet choisissent chacun le prochain saut d’après la destination et abaissent à nouveau le TTL.","New source":"Nouvelle source","Leaves home":"Quitte la maison","At the server":"Au serveur","TTL 116 (11 more hops)":"TTL 116 (11 sauts de plus)","TTL 127 · after NAT":"TTL 127 · après le NAT","The Reply Comes Back":"La réponse revient","NAT translates it for the laptop":"Le NAT la traduit pour l’ordinateur","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Le serveur répond à l’adresse qu’il a vue, 198.51.100.7:40112. Le routeur la cherche dans sa table NAT, réécrit la destination en 192.168.1.10:52344 et transmet. La réponse est partie avec un TTL de 64 et arrive avec 52.","Delivered to":"Livrée à","TTL 52 · after NAT":"TTL 52 · après le NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (après le NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (après le NAT)","ARP request · 28 bytes":"Requête ARP · 28 octets","Broadcast: every device on the network receives it.":"Diffusion : tous les appareils du réseau la reçoivent.","The sender’s network card.":"La carte réseau de l’émetteur.","Hardware type":"Type de matériel","Protocol type":"Type de protocole","Address sizes":"Tailles d’adresse",Operation:"Opération","1 (request: who has …?)":"1 (requête : qui a … ?)","Sender MAC":"MAC de l’émetteur","Sender IP":"IP de l’émetteur","Target MAC":"MAC cible","All zeros: this is what the request wants to find out.":"Que des zéros : c’est ce que la requête veut découvrir.","Target IP":"IP cible","ARP reply · 28 bytes":"Réponse ARP · 28 octets","Straight back to the device that asked.":"Directement à l’appareil qui a demandé.","2 (reply: … is at …)":"2 (réponse : … est à …)","Seen as it leaves the router’s internet side":"Vu à la sortie, côté Internet du routeur","The internet provider’s router, the next hop.":"Le routeur du fournisseur d’accès, le prochain saut.","The router’s internet-facing port.":"Le port du routeur côté Internet.","As sent: this system starts at 64.":"Tel qu’envoyé : ce système démarre à 64.","The router’s NAT swapped in its own port for the laptop’s.":"Le NAT du routeur a mis son propre port à la place de celui de l’ordinateur.","The sender’s next router; each hop puts the packet in a new frame.":"Le routeur suivant de l’émetteur ; à chaque saut, le paquet est placé dans une nouvelle trame.","Name Resolution":"Résolution de noms",Query:"Requête",Referral:"Référence","DNSSEC not requested here":"DNSSEC non demandé ici","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"Le DNS transforme des noms comme www.example.com en adresses IP, celles qu’utilisent les ordinateurs pour se joindre. Aucun serveur ne connaît tous les noms : le système est une hiérarchie de serveurs, et les réponses sont mises en cache en chemin, si bien que la plupart des résolutions n’ont jamais à aller loin.","53, UDP (TCP if large)":"53, UDP (TCP si volumineux)",Turns:"Transforme","Names into IP addresses":"Les noms en adresses IP",Hierarchy:"Hiérarchie","Root → TLD → authoritative":"Racine → TLD → autorité",Caching:"Cache","For each record’s TTL":"Pendant le TTL de chaque enregistrement","Name resolved":"Nom résolu","And remembered for an hour":"Et mémorisé pendant une heure","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Partant d’un cache vide, le résolveur est allé de la racine à .com puis au serveur d’example.com, avant de répondre à l’ordinateur. Tant que le TTL n’est pas écoulé, la prochaine résolution de ce nom vient directement d’un cache. Appuyez sur REVOIR pour tout revoir.",Queries:"Requêtes","4 (laptop 1, resolver 3)":"4 (ordinateur 1, résolveur 3)","Cached for":"En cache pendant","Ask the Resolver":"Demander au résolveur","The laptop hands the question off":"L’ordinateur délègue la question","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Le navigateur a besoin de l’adresse IP de www.example.com, et ni lui ni Windows ne l’ont en cache. L’ordinateur envoie une seule question au résolveur récursif qui lui a été attribué, 8.8.8.8, et lui demande de faire toute la résolution (récursion souhaitée).","www.example.com, type A":"www.example.com, type A",Asked:"Demandé à","8.8.8.8 (recursive)":"8.8.8.8 (récursif)","RD (recursion desired)":"RD (récursion souhaitée)","flags: RD":"drapeaux : RD","Points the way to .com":"Indique le chemin vers .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Le cache du résolveur est vide (il vient de démarrer), donc il commence par le sommet. Un serveur racine ne connaît pas l’adresse, mais il sait quels serveurs gèrent .com et répond par une référence. Beaucoup de résolveurs ne lui envoient que « com », pas le nom complet.","Root servers":"Serveurs racine","13 names, 1,000+ anycast sites":"13 noms, plus de 1,000 sites anycast","Referral (13 .com servers)":"Référence (13 serveurs .com)","no answer: ask .com":"pas de réponse : demandez à .com","Points the way to example.com":"Indique le chemin vers example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Le résolveur interroge un des serveurs .com. Eux non plus ne stockent pas l’adresse de chaque site, mais ils savent quels serveurs de noms utilise chaque domaine .com : cette réponse est donc une autre référence, avec les adresses de ces serveurs (glue) jointes.",Knows:"Connaît","Name servers of .com domains":"Les serveurs de noms des domaines .com","Referral + glue addresses":"Référence + adresses glue","no answer: ask example.com":"pas de réponse : demandez à example.com","Gives the actual answer":"Donne la vraie réponse","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Enfin, le résolveur interroge le serveur de noms d’example.com, qui détient les enregistrements du domaine. Il répond avec l’enregistrement A et marque la réponse comme faisant autorité. Le propriétaire du domaine fixe combien de temps elle peut rester en cache : ici, 3600 secondes.","AA (authoritative), TTL 3600":"AA (fait autorité), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · drapeau AA","Answer & Cache":"Réponse et cache","The laptop gets its address":"L’ordinateur obtient son adresse","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Le résolveur renvoie la réponse à l’ordinateur et en garde une copie. Pendant l’heure qui suit, il peut répondre aussitôt pour ce nom, ce qui explique pourquoi la résolution de la leçon HTTP n’a pris que 24 ms. L’ordinateur la met aussi en cache.","RD, RA (recursion available)":"RD, RA (récursion disponible)","Cached by":"En cache chez","Resolver and laptop":"Le résolveur et l’ordinateur","flags: RD RA":"drapeaux : RD RA","Referral: com. NS ×13 (with glue)":"Référence : com. NS ×13 (avec glue)","Referral: example.com. NS ×2 (with glue)":"Référence : example.com. NS ×2 (avec glue)","Response A 203.0.113.10 (authoritative)":"Réponse A 203.0.113.10 (fait autorité)","As sent: this system starts at 128.":"Tel qu’envoyé : ce système démarre à 128.","0x0000: query":"0x0000 : requête","UDP size 1232, DNSSEC OK = 0":"Taille UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Indique la taille maximale d’une réponse UDP. Les signatures DNSSEC ne sont pas demandées ici, pour garder la leçon courte ; un résolveur qui valide, comme 8.8.8.8, les demande.","0x8000: response":"0x8000 : réponse",Authority:"Autorité",Additional:"Additionnel","0x8400: response, AA (authoritative)":"0x8400 : réponse, AA (fait autorité)","Getting an Address":"Obtenir une adresse","From the laptop":"Depuis l’ordinateur","From the DHCP server":"Depuis le serveur DHCP","Dynamic Host Configuration Protocol":"Protocole de configuration dynamique des hôtes","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP donne à un appareil tout ce qu’il lui faut pour utiliser un réseau : une adresse IP, le masque de sous-réseau, le routeur par lequel faire passer le trafic et les serveurs DNS à interroger. Les adresses sont attribuées par bail pour une durée fixe et renouvelées tant que l’appareil reste sur le réseau.","UDP 67 (server), 68 (client)":"UDP 67 (serveur), 68 (client)","Hands out":"Distribue","IP, mask, gateway, DNS":"IP, masque, passerelle, DNS",Exchange:"Échange",Lease:"Bail","Renewed at half its time":"Renouvelé à mi-parcours","On the network":"Sur le réseau","Leased, and kept up to date":"Bail obtenu, et tenu à jour","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Quatre messages ont fait passer l’ordinateur d’aucune adresse à une configuration complète, et à la moitié du bail de 24 heures, il l’a renouvelé par une demande directe au routeur. Appuyez sur REVOIR pour tout revoir.",Messages:"Messages","4 to join, 2 per renewal":"4 pour rejoindre, 2 par renouvellement","24 h, renewed at 12 h":"24 h, renouvelé à 12 h","No Address Yet":"Pas encore d’adresse","The laptop joins the network":"L’ordinateur rejoint le réseau","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"L’ordinateur vient de se connecter. Il a une adresse MAC intégrée, mais ni adresse IP, ni passerelle, ni serveur DNS, donc il ne peut encore parler à rien au-delà de son propre réseau. Il les demande avec DHCP.","IP address":"Adresse IP","None (uses 0.0.0.0)":"Aucune (utilise 0.0.0.0)","MAC address":"Adresse MAC",Needs:"A besoin de",Discover:"Découverte","Shout to the whole network":"Crier à tout le réseau","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Sans adresse à lui, l’ordinateur envoie depuis 0.0.0.0 vers l’adresse de diffusion 255.255.255.255, si bien que tous les appareils du réseau local la reçoivent. Seuls les serveurs DHCP répondent.",From:"De","0.0.0.0, UDP port 68":"0.0.0.0, port UDP 68","255.255.255.255, port 67":"255.255.255.255, port 67",Carries:"Transporte","MAC, transaction ID":"MAC, ID de transaction","any DHCP server out there?":"un serveur DHCP dans le coin ?",Offer:"Offre","The router proposes an address":"Le routeur propose une adresse","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Le serveur DHCP du routeur choisit une adresse libre et la propose avec le reste des réglages. L’ordinateur ne peut pas encore utiliser d’adresse IP, donc l’offre va directement à son adresse MAC (certains clients demandent plutôt une diffusion).",Offered:"Proposée","Gateway, DNS":"Passerelle, DNS","offer: 192.168.1.10/24":"offre : 192.168.1.10/24","gateway, DNS, lease 24 h":"passerelle, DNS, bail de 24 h","Accept, out loud":"Accepter, à voix haute","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"L’ordinateur demande l’adresse proposée, en nommant le serveur qu’il a choisi. Il diffuse encore, si bien que tout autre serveur DHCP ayant fait une offre apprend qu’il n’a pas été retenu et peut libérer son adresse.",Requests:"Demande","Chosen server":"Serveur choisi","I’ll take 192.168.1.10":"Je prends 192.168.1.10","from server 192.168.1.1":"du serveur 192.168.1.1",Acknowledge:"Accusé de réception","The address is the laptop’s":"L’adresse est à l’ordinateur","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Le serveur confirme, et l’ordinateur configure son adresse, son masque, sa passerelle et son serveur DNS. Beaucoup de systèmes vérifient d’abord avec ARP qu’aucun autre appareil n’utilise déjà l’adresse.","DNS server":"Serveur DNS","192.168.1.10 is yours":"192.168.1.10 est à vous","for 24 hours":"pour 24 heures",Renew:"Renouvellement","Halfway through the lease":"À la moitié du bail","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Douze heures plus tard, la moitié du bail est écoulée. L’ordinateur a maintenant une adresse, il demande donc directement au routeur de prolonger le bail, et le routeur le remet à 24 heures. Sans réponse du routeur, il diffuserait à 87.5 %.",When:"Quand","50% of lease (T1 = 12 h)":"50 % du bail (T1 = 12 h)","The router (unicast)":"Le routeur (unicast)","If unanswered":"Sans réponse","Broadcast at 87.5% (T2)":"Diffusion à 87.5 % (T2)","renew 192.168.1.10":"renouveler 192.168.1.10","sent straight to 192.168.1.1":"envoyé directement à 192.168.1.1","lease renewed":"bail renouvelé","another 24 hours":"24 heures de plus",Message:"Message","1 (request, from a client)":"1 (requête, d’un client)",Hardware:"Matériel","Ethernet, 6-byte addresses":"Ethernet, adresses de 6 octets",Hops:"Sauts","Chosen by the client; every reply repeats it.":"Choisi par le client ; chaque réponse le répète.",Seconds:"Secondes","0x0000 (unicast replies are fine)":"0x0000 (les réponses unicast conviennent)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Drapeau de diffusion désactivé : le serveur peut envoyer directement à l’adresse MAC du client.","Client address":"Adresse du client","Filled in only when the client already has an address (renewing).":"Rempli seulement quand le client a déjà une adresse (renouvellement).","Your address":"Votre adresse","The address the server is giving out.":"L’adresse que le serveur attribue.","Next server":"Serveur suivant","Relay agent":"Agent relais","Client MAC":"MAC du client","Server name, boot file":"Nom du serveur, fichier de démarrage",empty:"vide","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Indique que les options qui suivent sont du DHCP.","Message type: 1 (Discover)":"Type de message : 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Identifiant client : 01 00:00:5e:00:53:10","Host name: alice-laptop":"Nom d’hôte : alice-laptop","Vendor class: MSFT 5.0":"Classe du fabricant : MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Paramètres voulus : 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (réponse, d’un serveur)","Message type: 2 (Offer)":"Type de message : 2 (Offer)","Server identifier: 192.168.1.1":"Identifiant du serveur : 192.168.1.1","Lease time: 86,400 s (24 h)":"Durée du bail : 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Délai de renouvellement (T1) : 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Délai de réassociation (T2) : 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Masque de sous-réseau : 255.255.255.0","Broadcast address: 192.168.1.255":"Adresse de diffusion : 192.168.1.255","DNS server: 8.8.8.8":"Serveur DNS : 8.8.8.8","Message type: 3 (Request)":"Type de message : 3 (Request)","Requested address: 192.168.1.10":"Adresse demandée : 192.168.1.10","Client FQDN: alice-laptop":"FQDN du client : alice-laptop","Message type: 5 (ACK)":"Type de message : 5 (ACK)","Network Diagnostics":"Diagnostic réseau","Ping / probe":"Ping / sonde","Echo reply":"Réponse d’écho","Error report":"Rapport d’erreur","Internet Control Message Protocol":"Protocole de messages de contrôle d’Internet","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP est la façon dont le réseau fait remonter des informations : un routeur signale que le temps d’un paquet est écoulé, un serveur signale que rien n’écoute sur un port. Des outils comme ping et traceroute reposent sur ces messages. Il voyage dans IP mais ne transporte aucune donnée d’application.","Carried in":"Transporté dans","IP (protocol 1)":"IP (protocole 1)","A type and a code":"Un type et un code",Tools:"Outils",Often:"Souvent","Filtered by firewalls":"Filtré par les pare-feu","The network answered":"Le réseau a répondu","Replies, expiries and errors":"Réponses, expirations et erreurs","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Une requête d’écho a mesuré l’aller-retour, des paquets à petit TTL ont poussé chaque routeur du chemin à se signaler, et un port fermé a été signalé aussitôt. Appuyez sur REVOIR pour tout revoir.","Round trip":"Aller-retour",Path:"Chemin","12 routers, server at hop 13":"12 routeurs, serveur au saut 13","Types used":"Types utilisés","8, 0, 11 and 3":"8, 0, 11 et 3","Reply TTL":"TTL de la réponse",Ping:"Ping","Echo request":"Requête d’écho","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"« ping -n 1 203.0.113.10 » envoie une requête d’écho ICMP (un ping simple en envoie quatre, à une seconde d’intervalle) : type 8, code 0, avec un identifiant, un numéro de séquence et 32 octets de remplissage. Le système du serveur répond tout seul, sans application.","Type, code":"Type, code","8, 0 (echo request)":"8, 0 (requête d’écho)","type 8 · seq 1":"type 8 · séq. 1","32 bytes of data":"32 octets de données","Echo Reply":"Réponse d’écho","Round-trip time":"Temps aller-retour","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Le serveur renvoie une réponse d’écho, type 0, avec le même identifiant, le même numéro de séquence et les mêmes données. Ping affiche le temps écoulé et le TTL avec lequel la réponse est arrivée : « octets=32 temps=34 ms TTL=52 ».","0, 0 (echo reply)":"0, 0 (réponse d’écho)","TTL on arrival":"TTL à l’arrivée","type 0 · seq 1":"type 0 · séq. 1","same 32 bytes back":"les mêmes 32 octets en retour","The first router answers":"Le premier routeur répond","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"« ping -n 1 -i 1 » envoie la même requête avec un TTL de 1. Le routeur de la maison l’abaisse à 0 : il doit donc jeter le paquet, et il renvoie un message « temps dépassé » (Time Exceeded) depuis sa propre adresse : « Réponse de 192.168.1.1 : TTL expiré lors du transit. »","Sent with":"Envoyé avec","Dropped by":"Jeté par","11, 0 (time exceeded)":"11, 0 (temps dépassé)","echo request":"requête d’écho","expires at the first router":"expire au premier routeur","type 11 · from 192.168.1.1":"type 11 · de 192.168.1.1","quotes the dropped header":"cite l’en-tête jeté","The next router answers":"Le routeur suivant répond","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Avec « -i 2 », le routeur de la maison abaisse le TTL à 1 et transmet. Le premier routeur du fournisseur d’accès l’abaisse à 0 et le signale depuis 198.51.100.1. Le routeur de la maison retraduit ce rapport pour l’ordinateur comme n’importe quelle réponse.","ISP router 198.51.100.1":"Routeur du FAI 198.51.100.1","expires at the second router":"expire au deuxième routeur","type 11 · from 198.51.100.1":"type 11 · de 198.51.100.1","That’s Traceroute":"C’est ça, traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … jusqu’à l’arrivée","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert automatise cela : il augmente le TTL de un à chaque fois, envoie trois sondes par saut et liste qui répond. Les sauts 3 à 12 fonctionnent de la même façon, et avec un TTL de 13, la requête atteint enfin le serveur, qui répond normalement.","12 routers, then the server":"12 routeurs, puis le serveur","Per hop":"Par saut","3 probes":"3 sondes","On Linux":"Sous Linux","traceroute sends UDP":"traceroute envoie de l’UDP","enough hops to arrive":"assez de sauts pour arriver","the server itself answers":"le serveur lui-même répond","end of the route":"fin de la route",Unreachable:"Injoignable","Nothing listening on that port":"Rien n’écoute sur ce port","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Une appli envoie un datagramme UDP au port 9999, où rien n’écoute. Le serveur ne peut pas le livrer, il répond donc par « destination injoignable », code 3 (port injoignable), en citant le début du datagramme. Beaucoup de pare-feu jettent plutôt ce genre de paquets sans rien dire.","3, 3 (port unreachable)":"3, 3 (port injoignable)","Other codes":"Autres codes","0 net, 1 host, 4 too big":"0 réseau, 1 hôte, 4 trop gros",Firewalls:"Pare-feu","Often silent instead":"Souvent muets à la place","to port 9999":"vers le port 9999","nothing listening there":"rien n’y écoute","type 3 · code 3":"type 3 · code 3","port unreachable":"port injoignable","ICMP · Echo request":"ICMP · Requête d’écho",Code:"Code","Covers the whole ICMP message.":"Couvre tout le message ICMP.",Identifier:"Identifiant","Matches replies to this ping program.":"Associe les réponses à ce programme ping.","Windows counts up across every ping it sends.":"Windows incrémente ce compteur sur tous les pings qu’il envoie.","Windows ping’s filler: the alphabet, a to w, then again.":"Le remplissage du ping de Windows : l’alphabet, de a à w, puis à nouveau.","ICMP · Echo reply":"ICMP · Réponse d’écho","Sent back exactly as it came.":"Renvoyé exactement tel qu’il est arrivé.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Temps dépassé (TTL arrivé à 0)","Time exceeded (TTL reached 0)":"Temps dépassé (TTL arrivé à 0)",Unused:"Inutilisé","Original packet":"Paquet d’origine","Its source, destination":"Sa source, sa destination","its IP header and first 8 bytes (28 bytes)":"son en-tête IP et ses 8 premiers octets (28 octets)","App data":"Données de l’appli","What the app sent; nothing on the server is listening for it.":"Ce que l’appli a envoyé ; rien sur le serveur ne l’attend.","ICMP · Destination unreachable (port unreachable)":"ICMP · Destination injoignable (port injoignable)","Destination unreachable (port unreachable)":"Destination injoignable (port injoignable)","Sending Email":"Envoyer un e-mail","SMTP command":"Commande SMTP","SMTP reply":"Réponse SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP achemine les e-mails : de votre appli de messagerie au serveur de votre fournisseur, puis de ce serveur à celui du destinataire. C’est une conversation de courtes commandes texte, chacune suivie d’un code de réponse à trois chiffres. Lire ses e-mails est une autre affaire, réglée par IMAP ou POP3.","465/587 submit, 25 relay":"465/587 envoi, 25 relais","TCP, usually with TLS":"TCP, généralement avec TLS",Commands:"Commandes",Replies:"Réponses","2xx ok, 3xx go on, 4/5xx error":"2xx OK, 3xx continuer, 4/5xx erreur","Mail delivered":"E-mail livré","Two hops, one message":"Deux étapes, un message","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"L’appli d’Alice a remis le message à son fournisseur par une connexion chiffrée et authentifiée. Le fournisseur a trouvé le serveur de messagerie de Bob dans le DNS et l’y a relayé, en passant ce lien en TLS. Le message attend maintenant dans la boîte de Bob jusqu’à ce qu’il le lise avec IMAP ou POP3.","Laptop → provider → Bob’s":"Ordinateur → fournisseur → Bob",Submission:"Envoi","Port 465, TLS, login":"Port 465, TLS, connexion",Relay:"Relais","Port 25, STARTTLS":"Port 25, STARTTLS","Checks at Bob’s":"Vérifications chez Bob","Connect Securely":"Se connecter en sécurité","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice appuie sur Envoyer. Son appli de messagerie se connecte au serveur d’envoi de son fournisseur, smtp.example.com, sur le port 465. Sur ce port, TLS démarre immédiatement : toute la conversation SMTP, mot de passe compris, est donc chiffrée.","TLS from the start":"TLS dès le départ","SMTP inside TLS":"SMTP dans TLS","Greeting & Login":"Accueil et connexion","EHLO, then AUTH":"EHLO, puis AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Le serveur salue avec le code 220. L’appli dit EHLO et le serveur liste ce qu’il prend en charge, dont AUTH. L’appli se connecte avec AUTH PLAIN (nom d’utilisateur et mot de passe, encodés en base64) et reçoit 235 : authentifiée.",Greeting:"Accueil",Capabilities:"Capacités","Login result":"Résultat de la connexion","user and password, base64":"utilisateur et mot de passe, en base64","Send the Message":"Envoyer le message","Envelope, then content":"L’enveloppe, puis le contenu","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM et RCPT TO forment l’enveloppe : expéditeur et destinataire. PIPELINING permet aux trois commandes de partager un seul paquet. Après le 354 vient le message, terminé par une ligne ne contenant qu’un point.",Envelope:"Enveloppe","Content ends":"Fin du contenu","A line with only “.”":"Une ligne avec seulement « . »",Result:"Résultat","… message …":"… message …","Find Bob’s Server":"Trouver le serveur de Bob","An MX lookup in DNS":"Une recherche MX dans le DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Le fournisseur d’Alice doit maintenant livrer à example.org. Il demande au DNS l’enregistrement MX de ce domaine, qui nomme le serveur acceptant son courrier, puis cherche l’adresse de ce serveur.","MX record":"Enregistrement MX","Asked by":"Demandé par","Alice’s provider":"Le fournisseur d’Alice","Server to Server":"De serveur à serveur","Port 25, upgraded with STARTTLS":"Port 25, sécurisé avec STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Le fournisseur se connecte à mx.example.org sur le port 25. Cette conversation commence en clair : l’accueil et la réponse à EHLO annoncent STARTTLS, le fournisseur le demande, reçoit 220, et les deux côtés passent en TLS.","Starts as":"Commence en","Plain text":"Texte en clair",Upgrade:"Passage en TLS",Deliver:"Livrer","The same transaction again":"La même transaction, à nouveau","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Une fois TLS actif, le fournisseur répète EHLO, puis l’enveloppe et le message, désormais avec une signature DKIM et un en-tête Received ajoutés. Le serveur de Bob vérifie SPF, DKIM et DMARC et l’accepte.","Login needed":"Connexion requise","No (server to server)":"Non (de serveur à serveur)","1,316 bytes (signed)":"1,316 octets (signé)","Server Hello + encrypted handshake, 2 segments":"Server Hello + poignée de main chiffrée, 2 segments","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 capacités (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (identifiants)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (en pipeline)","Message (316 bytes), then “.”":"Message (316 octets), puis « . »","250 capabilities (PIPELINING, STARTTLS …)":"250 capacités (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 capacités (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Message (1,316 octets), puis « . »","What this client supports. Its exact contents vary from client to client; this is an example.":"Ce que ce client prend en charge. Le contenu exact varie d’un client à l’autre ; ceci est un exemple.","up to 512 bytes":"jusqu’à 512 octets","The server’s choices and its key share.":"Les choix du serveur et sa part de clé.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (la chaîne), Certificate Verify (la signature), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Le message d’Alice (316 octets), puis une ligne ne contenant que « . »","example.org, type MX, class IN":"example.org, type MX, classe IN","mx.example.org, type A, class IN":"mx.example.org, type A, classe IN",Timestamps:"Horodatages","Used to measure round trips; both sides offered them.":"Servent à mesurer les allers-retours ; les deux côtés les ont proposés.","The signed message (1,316 bytes), then a line holding only “.”":"Le message signé (1,316 octets), puis une ligne ne contenant que « . »","Downloading Email":"Télécharger ses e-mails","POP3 command":"Commande POP3","POP3 reply":"Réponse POP3","Post Office Protocol, version 3":"Protocole de bureau de poste, version 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 permet à une appli de messagerie de télécharger les messages d’une boîte aux lettres sur un serveur. Il a été conçu pour un seul appareil qui récupère le courrier puis le supprime du serveur. Les commandes sont des mots courts, et chaque réponse commence par +OK ou -ERR.",Model:"Modèle","Download, then delete":"Télécharger, puis supprimer","Mail downloaded":"Courrier téléchargé","And gone from the server":"Et disparu du serveur","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"L’appli de Bob s’est connectée, a vu deux messages, a téléchargé le premier puis l’a supprimé, ce que le serveur a exécuté au QUIT. Ce message n’existe plus que sur cet ordinateur : voilà pourquoi POP3 convient à un seul appareil et IMAP à plusieurs.","2 waiting, 1 downloaded":"2 en attente, 1 téléchargé",Deleted:"Supprimé","At QUIT (UPDATE state)":"Au QUIT (état UPDATE)","Best for":"Idéal pour","A single device":"Un seul appareil","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"L’appli de messagerie de Bob se connecte à pop.example.org sur le port 995, où TLS démarre tout de suite. À l’intérieur, le serveur salue avec +OK. (Sur le port 110, la session commence en clair et passe en TLS avec la commande STLS.)","USER, then PASS":"USER, puis PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"L’appli envoie le nom d’utilisateur avec USER et le mot de passe avec PASS. Chaque commande reçoit son propre +OK. Comme la session est dans TLS, le mot de passe n’est pas lisible en chemin.","Protected by":"Protégé par","Check the Mailbox":"Consulter la boîte","STAT and LIST":"STAT et LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT renvoie le nombre de messages et leur taille totale : 2 messages, 5120 octets. LIST donne le numéro et la taille de chaque message, et se termine par une ligne ne contenant qu’un point.","Message 1":"Message 1","Message 2":"Message 2",Download:"Télécharger","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 demande le premier message. Le serveur répond +OK avec sa taille, puis le message et un point final : 1904 octets plus la ligne de réponse, deux segments TCP.",Command:"Commande","Delete & Quit":"Supprimer et quitter","Deleted only at QUIT":"Supprimé seulement au QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 ne fait que marquer le message. Le serveur le supprime quand l’appli dit QUIT : si la connexion tombait avant, rien ne serait supprimé. Beaucoup d’applis proposent « laisser une copie sur le serveur », ce qui saute DELE.","Marks message 1":"Marque le message 1",Removed:"Supprimé",Option:"Option","Leave a copy on server":"Laisser une copie sur le serveur","PASS (password)":"PASS (mot de passe)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, message, « . » (2 segments)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, le message de 1,904 octets, puis une ligne ne contenant que « . »","Mail That Stays in Sync":"Un courrier toujours synchronisé","IMAP command":"Commande IMAP","IMAP response":"Réponse IMAP","Internet Message Access Protocol":"Protocole d’accès aux messages Internet","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP permet aux applis de messagerie de travailler sur une boîte aux lettres qui reste sur le serveur. Les dossiers, les marques lu et suivi et les suppressions y sont conservés : un téléphone, un ordinateur et le webmail voient donc la même boîte. Le serveur peut aussi prévenir une appli de l’arrivée d’un nouveau courrier.","Mail stays on the server":"Le courrier reste sur le serveur",Syncs:"Synchronise","Folders and flags":"Dossiers et indicateurs","Mailbox in sync":"Boîte synchronisée","Read once, read everywhere":"Lu une fois, lu partout","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"L’appli de Bob a ouvert sa boîte de réception et lu un message, ce qui l’a marqué \\Seen sur le serveur pour tous ses appareils, puis elle a attendu avec IDLE que le serveur annonce un nouveau courrier. Rien n’a été supprimé : le serveur garde tout.","2, then 3 (new mail)":"2, puis 3 (nouveau courrier)","Read mark":"Marque de lecture","\\Seen, stored on server":"\\Seen, stocké sur le serveur","New mail":"Nouveau courrier","Pushed during IDLE":"Poussé pendant IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"L’appli de Bob se connecte à imap.example.org sur le port 993, où TLS démarre tout de suite. Le serveur salue avec une ligne « * OK » sans étiquette, qui liste aussi ses capacités, comme IDLE.","Commands carry tags":"Les commandes portent des étiquettes","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Chaque commande commence par une étiquette choisie par l’appli, comme a1, et le serveur termine sa réponse par la même étiquette. Ainsi, plusieurs commandes peuvent être en cours et chaque réponse est associée à la bonne. Les lignes commençant par * sont des données sans étiquette.",Tags:"Étiquettes","Match replies to commands":"Associer réponses et commandes","Open the Inbox":"Ouvrir la boîte de réception","SELECT a folder":"SELECT sur un dossier","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX ouvre le dossier. Le serveur indique le nombre de messages, les indicateurs qu’il gère et le premier message non lu, puis confirme que le dossier est ouvert en lecture-écriture.","First unread":"Premier non lu",Access:"Accès","Read a Message":"Lire un message","FETCH, and the \\Seen flag":"FETCH, et l’indicateur \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] télécharge le message 2 (trois segments TCP). Cela active son indicateur \\Seen sur le serveur, il apparaît donc comme lu sur le téléphone de Bob aussi, et le message y reste.","Flag set":"Indicateur activé","\\Seen (on the server)":"\\Seen (sur le serveur)","Wait for New Mail":"Attendre un nouveau courrier","IDLE: the server pushes":"IDLE : le serveur pousse","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE dit au serveur « préviens-moi quand quelque chose change ». Environ 42 secondes plus tard, le message d’Alice arrive et le serveur pousse aussitôt « * 3 EXISTS ». L’appli met fin à IDLE avec DONE et peut récupérer le nouveau courrier.","Server says":"Le serveur dit","* 3 EXISTS (new mail)":"* 3 EXISTS (nouveau courrier)","Ended by":"Terminé par","a1 LOGIN (user and password)":"a1 LOGIN (utilisateur et mot de passe)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, le message de 3,216 octets, puis a3 OK FETCH completed","Transferring Files":"Transférer des fichiers","FTP command":"Commande FTP","FTP reply":"Réponse FTP","File data":"Données du fichier","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP transfère des fichiers entre un client et un serveur. Il a la particularité d’utiliser deux connexions TCP : une pour les commandes et les réponses, et une nouvelle pour chaque fichier ou listing. Il date du début des années 1970 et envoie tout en clair, mots de passe compris.","21 control, data varies":"21 contrôle, données variables",Connections:"Connexions","Control + one per transfer":"Contrôle + une par transfert",Encryption:"Chiffrement","None (plain text)":"Aucun (texte en clair)","Safer options":"Options plus sûres","File downloaded":"Fichier téléchargé","Two connections, no encryption":"Deux connexions, aucun chiffrement","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Les commandes sont passées par la connexion de contrôle, le fichier par sa propre connexion de données, et la fermeture de celle-ci a marqué la fin du fichier. N’importe qui sur le chemin aurait pu lire le mot de passe et le fichier : voilà pourquoi on utilise aujourd’hui SFTP ou FTPS.","2 (control + data)":"2 (contrôle + données)",File:"Fichier","4,000 bytes, 3 segments":"4,000 octets, 3 segments",Password:"Mot de passe","Sent in plain text":"Envoyé en clair","Use instead":"Utiliser plutôt","Control Connection":"Connexion de contrôle","Port 21, plain text":"Port 21, texte en clair","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"L’appli FTP ouvre une connexion TCP vers ftp.example.com sur le port 21. Cette connexion de contrôle transporte les commandes et les réponses de toute la session. Le serveur salue avec 220. Comme pour SMTP, chaque réponse commence par un code à trois chiffres.","USER and PASS, readable by anyone":"USER et PASS, lisibles par tous","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"L’appli envoie USER, le serveur demande le mot de passe avec 331, et PASS l’envoie. Rien n’est chiffré : le nom d’utilisateur et le mot de passe traversent tous les réseaux du chemin en texte lisible.","Visible to":"Visible par","Anyone on the path":"N’importe qui sur le chemin","Passive Mode":"Mode passif","The server names a data port":"Le serveur indique un port de données","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I demande une copie binaire octet par octet. PASV demande au serveur d’ouvrir un port pour la connexion de données. La réponse code l’adresse et le port en six nombres : 195 × 256 + 149 = port 50069. L’ordinateur se connecte vers l’extérieur, ce qui passe à travers le NAT.","Data port":"Port de données","Active mode":"Mode actif","Server dials in: NAT blocks":"Le serveur rappelle : le NAT bloque","Data Connection":"Connexion de données","A second TCP connection":"Une seconde connexion TCP","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"L’appli ouvre une seconde connexion TCP, vers le port 50069, et demande le fichier sur la connexion de contrôle avec RETR. Le serveur y répond 150 et commence à envoyer le fichier sur la nouvelle connexion.","Data to":"Données vers","The File Arrives":"Le fichier arrive","Closing the connection ends it":"Fermer la connexion marque la fin","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"Les 4,000 octets arrivent en 3 segments TCP. FTP n’envoie aucune indication de longueur dans les données elles-mêmes : le serveur ferme la connexion de données pour marquer la fin du fichier. Une fois que l’ordinateur a tout acquitté, le serveur confirme avec 226 sur la connexion de contrôle.","End of file":"Fin du fichier","Data connection closed":"Connexion de données fermée","4,000 bytes, readable by anyone":"4,000 octets, lisibles par tous","end of file:":"fin du fichier :","data connection closed":"connexion de données fermée",Quit:"Quitter","Close the control connection":"Fermer la connexion de contrôle","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT met fin à la session et le serveur dit au revoir avec 221. Pour tout ce qui est sensible, SFTP (un autre protocole, qui passe par SSH) ou FTPS (FTP dans TLS) font le même travail avec chiffrement.","Encrypted cousins":"Cousins chiffrés","FTP data":"Données FTP","The file itself, unencrypted: anyone on the path could read it.":"Le fichier lui-même, non chiffré : n’importe qui sur le chemin pourrait le lire.","Secure Remote Login":"Connexion à distance sécurisée","Plain setup":"Mise en place en clair","From laptop":"Depuis l’ordinateur","From server":"Depuis le serveur","Some packets not shown":"Certains paquets ne sont pas montrés","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH vous donne une connexion chiffrée et authentifiée vers un autre ordinateur, pour y exécuter des commandes, copier des fichiers (SFTP, scp) ou transporter d’autres connexions. Le serveur prouve son identité avec une clé d’hôte ; vous prouvez la vôtre avec une paire de clés ou un mot de passe.","Server proves":"Le serveur prouve","Host key (known_hosts)":"Clé d’hôte (known_hosts)","You prove":"Vous prouvez","Key pair or password":"Paire de clés ou mot de passe","Logged in securely":"Connecté en sécurité","Encrypted from the key exchange on":"Chiffré dès l’échange de clés","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Les deux côtés se sont mis d’accord sur les algorithmes, ont construit des clés communes avec un échange hybride post-quantique, et le serveur a prouvé son identité avec sa clé d’hôte. Alice a prouvé la sienne en signant avec une clé privée qui n’a jamais quitté l’ordinateur, puis a tapé une commande, un paquet par touche.",Login:"Connexion","Ed25519 key, no password":"Clé Ed25519, sans mot de passe","Say Hello":"Dire bonjour","Versions, in plain text":"Les versions, en clair","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice lance « ssh alice@server.example.com ». Après la poignée de main TCP sur le port 22, chaque côté envoie une ligne de texte en clair indiquant la version du protocole SSH (2.0) et son logiciel. Tout le reste de SSH est binaire.","Agree on Algorithms":"Négocier les algorithmes","KEXINIT lists, first match wins":"Listes KEXINIT, la première correspondance l’emporte","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Chaque côté envoie un KEXINIT listant tous les algorithmes qu’il prend en charge, par ordre de préférence, pour l’échange de clés, les clés d’hôte, le chiffrement, l’intégrité et la compression. Dans chaque catégorie, on choisit le premier algorithme de la liste de l’ordinateur que le serveur prend aussi en charge.","Host key":"Clé d’hôte","server’s algorithm lists":"listes d’algorithmes du serveur","in order of preference":"par ordre de préférence","laptop’s algorithm lists":"listes d’algorithmes de l’ordinateur","Key Exchange":"Échange de clés","Shared keys, and a host key check":"Des clés communes, et une vérification de la clé d’hôte","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"L’ordinateur envoie sa moitié d’un échange hybride : une clé Streamlined NTRU Prime, choisie pour résister aux futurs ordinateurs quantiques, plus une clé X25519. Le serveur répond avec sa moitié, sa clé d’hôte et une signature sur l’échange. NEWKEYS active le chiffrement.",Hybrid:"Hybride","Matches known_hosts":"Correspond à known_hosts","First visit":"Première visite","ssh asks you to confirm":"ssh vous demande de confirmer","public keys":"clés publiques","its half, its host key":"sa moitié, sa clé d’hôte","and a signature":"et une signature","Log In with a Key":"Se connecter avec une clé","Sign, don’t send a secret":"Signer, sans envoyer de secret","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Le serveur liste les méthodes de connexion qu’il accepte. L’ordinateur propose la clé publique d’Alice, et le serveur répond qu’il l’accepterait. L’ordinateur signe alors cette session avec la clé privée, qui ne quitte jamais l’ordinateur. Le serveur vérifie la signature grâce à authorized_keys.",Methods:"Méthodes","Ed25519, private stays here":"Ed25519, la privée reste ici","Checked with":"Vérifiée avec","alice’s public key":"clé publique d’alice","would you accept it?":"l’accepteriez-vous ?","yes, that key":"oui, cette clé","is in authorized_keys":"est dans authorized_keys","same key, plus a signature":"la même clé, plus une signature","made with the private key":"faite avec la clé privée","logged in":"connexion réussie","Open a Session":"Ouvrir une session","Channels inside one connection":"Des canaux dans une seule connexion","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Une connexion SSH peut transporter de nombreux canaux : un shell, des transferts de fichiers, des ports redirigés. L’ordinateur ouvre un canal de session, puis demande un terminal et un shell (non montrés), et le serveur envoie son texte d’accueil et une invite.",Channel:"Canal",session:"session","Then asks for":"Puis demande","A terminal and a shell":"Un terminal et un shell","Also possible":"Aussi possible","SFTP, port forwarding":"SFTP, redirection de ports","open a channel:":"ouvrir un canal :","channel open":"canal ouvert","Type a Command":"Taper une commande","Every key is a packet":"Chaque touche est un paquet","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice tape pwd. Chaque touche part aussitôt dans son propre paquet chiffré, et le serveur renvoie le caractère pour l’afficher (l’écho). Depuis la version 9.5, OpenSSH envoie les touches sur un rythme de 20 ms et ajoute des paquets leurres, pour que le rythme de frappe soit plus difficile à deviner d’après le minutage.","Per key":"Par touche","1 packet, 90 bytes":"1 paquet, 90 octets",Echo:"Écho","Sent back by the server":"Renvoyé par le serveur",Timing:"Minutage","20 ms beat plus decoys":"Rythme de 20 ms plus des leurres","Enter key":"Touche Entrée","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (clés publiques sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (clé d’hôte, sa moitié, signature)","Encrypted (len=44): service request, ssh-userauth":"Chiffré (len=44) : demande de service, ssh-userauth","Encrypted (len=44): service accept":"Chiffré (len=44) : service accepté","Encrypted (len=68): login with method none":"Chiffré (len=68) : connexion avec la méthode none","Encrypted (len=52): try publickey,password":"Chiffré (len=52) : essayez publickey,password","Encrypted (len=140): offer public key":"Chiffré (len=140) : propose une clé publique","Encrypted (len=100): public key OK":"Chiffré (len=100) : clé publique OK","Encrypted (len=308): public key + signature":"Chiffré (len=308) : clé publique + signature","Encrypted (len=28): login success":"Chiffré (len=28) : connexion réussie","Encrypted (len=52): channel open: session":"Chiffré (len=52) : ouverture de canal : session","Encrypted (len=44): channel open confirmed":"Chiffré (len=44) : ouverture du canal confirmée","Encrypted (len=36): keystroke":"Chiffré (len=36) : frappe","Encrypted (len=36): echo":"Chiffré (len=36) : écho","Encrypted (len=36): keystroke (Enter)":"Chiffré (len=36) : frappe (Entrée)","Encrypted (len=132): output and a new prompt":"Chiffré (len=132) : sortie et nouvelle invite","Packet length":"Longueur du paquet","Bytes after this field.":"Octets après ce champ.","Padding length":"Longueur du bourrage","Random padding brings the packet to a multiple of 8 bytes.":"Un bourrage aléatoire porte le paquet à un multiple de 8 octets.",Cookie:"Cookie","Host keys":"Clés d’hôte","Ciphers, out":"Chiffrements, sortie","Ciphers, in":"Chiffrements, entrée","MACs, out":"MAC, sortie","Compression, out":"Compression, sortie","Compression, in":"Compression, entrée","Languages, out":"Langues, sortie","Languages, in":"Langues, entrée","First packet follows":"Le premier paquet suit",Reserved:"Réservé","Public keys":"Clés publiques","51 bytes: ssh-ed25519 public key":"51 octets : clé publique ssh-ed25519","Server’s half":"Moitié du serveur","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 octets (texte chiffré sntrup761 1,039 + X25519 32)",Signature:"Signature","83 bytes: ssh-ed25519 signature over the exchange":"83 octets : signature ssh-ed25519 sur l’échange","From the next packet on, this side encrypts.":"À partir du paquet suivant, ce côté chiffre.","SSH · encrypted packet":"SSH · paquet chiffré","Encrypted packet":"Paquet chiffré","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Avec chacha20-poly1305, même la longueur est chiffrée ; une étiquette de 16 octets à la fin révèle toute modification.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50) : utilisateur « alice », service « ssh-connection », méthode « none »","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51) : méthodes pouvant continuer : « publickey,password »","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50) : méthode « publickey », sans signature, la clé publique ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60) : la même clé ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50) : méthode « publickey-hostbound-v00@openssh.com », la clé, la clé d’hôte du serveur et une signature","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90) : « session », canal 0, fenêtre de 2 Mo, paquets jusqu’à 32 Ko","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91) : le canal 0 est ouvert","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « p »","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « p », renvoyé pour être affiché","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « w »","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « w », renvoyé pour être affiché","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « d »","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, « d », renvoyé pour être affiché","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 1 octet, un retour chariot (Entrée)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), canal 0 : 94 octets : un saut de ligne, les codes de terminal du shell, « /home/alice » et l’invite en couleur","Encryption Explained":"Le chiffrement expliqué","From browser":"Depuis le navigateur","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS installe un canal sécurisé au-dessus de TCP. Il prouve l’identité du serveur avec un certificat, convient de clés neuves, puis chiffre et authentifie tout ce qui est envoyé. HTTPS, l’e-mail sécurisé et bien d’autres protocoles fonctionnent à l’intérieur. SSL était le nom de son prédécesseur.",Sits:"Se situe","Between TCP and the app":"Entre TCP et l’appli","OSI layer":"Couche OSI","Often placed at 6":"Souvent placé en 6",Current:"Actuelle",Retired:"Retirées","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 et 3, TLS 1.0 et 1.1","The app’s own (443, 993 …)":"Celui de l’appli (443, 993 …)","Secure from start to finish":"Sécurisé de bout en bout","One round trip to set up":"Un aller-retour pour l’établir","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Un seul aller-retour a suffi pour convenir d’une version, d’un chiffrement et d’une clé hybride post-quantique. La chaîne de certificats a prouvé qui était le serveur, et chaque octet après le Server Hello a été chiffré et authentifié, jusqu’au close_notify. Appuyez sur REVOIR pour tout revoir.","1 round trip":"1 aller-retour","Everything the browser supports":"Tout ce que le navigateur prend en charge","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Après la poignée de main TCP, le navigateur liste ce qu’il sait faire : versions de TLS, suites de chiffrement et parts de clé pour les groupes qu’il attend, dont l’hybride post-quantique X25519MLKEM768. Il nomme aussi le site (SNI) et les protocoles qu’il parle (ALPN).",Versions:"Versions","versions, ciphers, key shares":"versions, chiffrements, parts de clé","Choices made, keys computed":"Choix faits, clés calculées","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Le serveur choisit TLS 1.3, la suite de chiffrement et le groupe hybride, et envoie sa propre part de clé. À partir des deux parts, les deux côtés calculent le même secret sans qu’il traverse jamais le réseau. Tout ce qui suit ce message est chiffré.",Group:"Groupe","From here on":"À partir d’ici","its key share":"sa part de clé",Certificate:"Certificat","Who the server is, proven":"L’identité du serveur, prouvée","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Désormais chiffré, l’envoi continue : le protocole choisi (http/1.1), la chaîne de certificats, une signature faite avec la clé privée du certificat, et Finished.",Chain:"Chaîne","Site → intermediate → root":"Site → intermédiaire → racine","Proves the private key":"Prouve la clé privée",Checked:"Vérifié","Name, dates, trusted root":"Nom, dates, racine de confiance","encrypted: http/1.1, certificates,":"chiffré : http/1.1, certificats,","signature, Finished":"signature, Finished","One round trip, then data":"Un aller-retour, puis les données","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Le navigateur envoie son propre Finished : une valeur de contrôle sur tout ce que les deux côtés se sont dit, calculée avec le nouveau secret, si bien que toute falsification des hellos se verrait. TLS 1.3 n’a besoin que d’un aller-retour avant que les données circulent ; TLS 1.2 en demandait deux.",Covers:"Couvre","The whole handshake":"Toute la poignée de main","For old middleboxes":"Pour les vieux équipements intermédiaires","check value over":"valeur de contrôle sur","the whole handshake":"toute la poignée de main","Encrypted Data":"Données chiffrées","Records, tags and tickets":"Enregistrements, étiquettes et tickets","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP voyage maintenant dans des enregistrements chiffrés, chacun avec une étiquette de 16 octets qui révèle toute modification. Le serveur envoie aussi deux tickets de session : la prochaine fois, le navigateur pourra reprendre avec l’un d’eux et sauter le certificat.","Per record":"Par enregistrement","22 bytes of overhead":"22 octets de surcoût","2, for resuming later":"2, pour reprendre plus tard",Visible:"Visible","IPs, SNI, sizes, timing":"IP, SNI, tailles, minutage","2 session tickets":"2 tickets de session","for resuming later":"pour reprendre plus tard",Closing:"Fermeture","close_notify, then TCP":"close_notify, puis TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Après 75 secondes d’inactivité, le serveur ferme la connexion. Il envoie d’abord une alerte close_notify, chiffrée comme tout le reste, pour que le navigateur sache que les données se sont arrêtées volontairement et n’ont pas été coupées par un attaquant. Puis TCP se ferme comme d’habitude.",Alert:"Alerte","Shows nothing was cut off":"Montre que rien n’a été coupé","TCP FIN from both sides":"TCP FIN des deux côtés","alert: close_notify":"alerte : close_notify",encrypted:"chiffré","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ chiffré)","Encrypted handshake (continued)":"Poignée de main chiffrée (suite)","Encrypted handshake (certificate, verify, Finished)":"Poignée de main chiffrée (certificat, vérification, Finished)","Application Data (inside: close_notify alert)":"Application Data (à l’intérieur : alerte close_notify)","Alert: close_notify (the data ends here, on purpose)":"Alerte : close_notify (les données s’arrêtent ici, volontairement)","No IP address":"Pas d’adresse IP","192.168.1.1 · DHCP server":"192.168.1.1 · serveur DHCP"},r=e=>`${e} ${e==="1"?"octet":"octets"}`,n=e=>`${e} ${e==="1"?"enregistrement":"enregistrements"}`,c={strings:{...d,...u},patterns:[[/^([\d,]+) bytes$/,(e,t)=>r(t)],[/^(Ethernet II|IPv4|UDP|TCP) · (\d+) bytes$/,"$1 · $2 octets"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,(e,t,s)=>`${t}, ${r(s)}`],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 octets : report.pdf, octets $2"],[/^(.+) h later$/,"$1 h plus tard"],[/^(.+) min later$/,"$1 min plus tard"],[/^(.+) s later$/,"$1 s plus tard"],[/^(\S+) \(relative\)$/,"$1 (relatif)"],[/^(\d+) \(ephemeral\)$/,"$1 (éphémère)"],[/^(\d+) TCP segments$/,"$1 segments TCP"],[/^(\d+) segments$/,"$1 segments"],[/^(.*), (\d+) segments$/,"$1, $2 segments"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(e,t,s,a)=>`TLS 1.3 · ${n(t)} · octets ${s} sur ${a}`],[/^TLS 1\.3 · (\d+) records?$/,(e,t)=>`TLS 1.3 · ${n(t)}`],[/^Ethernet padding · (\d+) bytes$/,"Bourrage Ethernet · $1 octets"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 octets à zéro, jusqu’au minimum de 300 octets"],[/^(\d+) zero bytes$/,"$1 octets à zéro"],[/^(\d+) random bytes$/,"$1 octets aléatoires"],[/^Seen as it leaves (.+)$/,"Vu à la sortie de $1"],[/^Option (\d+)$/,"Option $1"],[/^value (\d+), echo (\d+)$/,"valeur $1, écho $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 octets, plus $1 d’options."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows démarre à $1. Réglé ici à $2 exprès."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(e,t,s)=>s==="1"?`Parti de ${t} ; le routeur sur le chemin a retiré 1.`:`Parti de ${t} ; chacun des ${s} routeurs sur le chemin a retiré 1.`],[/^all (\d+) bytes of it$/,"ses $1 octets en entier"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Le paquet qui a causé ceci, tel que l’appareil qui le signale l’a reçu (TTL $1), pour que l’émetteur sache de quel paquet il s’agit."],[/^Port (\d+), TLS from the start$/,"Port $1, TLS dès le départ"],[/^(\d+), TLS from the start$/,"$1, TLS dès le départ"]],post:e=>o(i(e))};export{c as default};
